def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-10):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

def check_partition(name: str, got):
    # same clustering up to a relabeling (eigenvector order/sign freedom)
    want = _get(name)
    g = np.asarray(got).ravel()
    ok = g.size == len(want)
    if ok:
        fwd = Dict[int, int]()
        bwd = Dict[int, int]()
        for i in range(len(want)):
            a = int(g[i])
            b = int(want[i])
            if a in fwd and fwd[a] != b:
                ok = False
            if b in bwd and bwd[b] != a:
                ok = False
            fwd[a] = b
            bwd[b] = a
    if not ok:
        print("TEST FAILED:", name, g, want)

rng = np.random.RandomState(0)
X = np.vstack([rng.randn(30, 2) * 0.4 + np.array([0., 0.]), rng.randn(30, 2) * 0.4 + np.array([4., 4.]),
               rng.randn(30, 2) * 0.4 + np.array([0., 5.])])

m = MiniBatchKMeans(n_clusters=3, random_state=0, batch_size=20).fit(X)
check("mbk_centers", m.cluster_centers_)
check("mbk_labels", m.labels_)
check("mbk_meta", [m.inertia_, float(m.n_iter_), float(m.n_steps_)])
m2 = MiniBatchKMeans(n_clusters=4, init="random", random_state=3, batch_size=16, n_init=2).fit(X)
check("mbk2_centers", m2.cluster_centers_)
check("mbk2_meta", [m2.inertia_, float(m2.n_iter_), float(m2.n_steps_)])

bw = estimate_bandwidth(X, quantile=0.2)
check("bandwidth", [bw])
ms = MeanShift(bandwidth=bw).fit(X)
check("ms_centers", ms.cluster_centers_)
check("ms_labels", ms.labels_)
ms2 = MeanShift(bandwidth=1.5, bin_seeding=True).fit(X)
check("ms2_centers", ms2.cluster_centers_)
check("ms2_predict", ms2.predict(np.array([[0.1, 0.2], [3.9, 4.2], [0.3, 4.6]])))

ap = AffinityPropagation(random_state=0).fit(X)
check("ap_centers_idx", ap.cluster_centers_indices_)
check("ap_labels", ap.labels_)
check("ap_niter", [float(ap.n_iter_)])
ap2 = AffinityPropagation(random_state=1, preference=-50.0, damping=0.7).fit(X)
check("ap2_centers_idx", ap2.cluster_centers_indices_)
check("ap2_niter", [float(ap2.n_iter_)])

check_partition("sc_kmeans", SpectralClustering(n_clusters=3, random_state=0, gamma=0.5, assign_labels="kmeans").fit(X).labels_)
check_partition("sc_discretize", SpectralClustering(n_clusters=3, random_state=0, gamma=0.5, assign_labels="discretize").fit(X).labels_)
check_partition("sc_cluster_qr", SpectralClustering(n_clusters=3, random_state=0, gamma=0.5, assign_labels="cluster_qr").fit(X).labels_)
check_partition("sc_nn", SpectralClustering(n_clusters=3, random_state=0, affinity="nearest_neighbors", n_neighbors=8,
                                            assign_labels="discretize").fit(X).labels_)
